    meetingKey: meeting.key,
    meetingStart: meeting.start,
    organizerEmail: meeting.organizerEmail,
    internalAttendeeEmails: meeting.internalAttendees.map(function (a) { return a.email; }),
    externalEmails: emails,
    domains: domains,
    account: null,
    contacts: {},
    domainCompanyIds: [],
    contactCompanyIds: {},
    companyIds: [],
    companies: {},
    dealLinks: {},
    dealIds: [],
    deals: {},
    relevantDealIds: [],
    dealNoteIds: {},
    notes: {},
    companyTicketIds: {},
    tickets: {},
