        path: '/crm/v3/objects/contacts/search',
        body: {
          filterGroups: [{ filters: [{ propertyName: 'email', operator: 'IN', values: state.externalEmails.slice(0, 100) }] }],
          properties: CONTACT_PROPERTIES,
