        method: 'POST',
        path: '/crm/v3/objects/companies/search',
        body: {
          filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: state.domains.slice(0, 100) }] }],
          properties: ['domain', 'name'],
