function oneOf(value, fallback, allowed, name) {
  const choice = isBlank(value) ? fallback : String(value).trim().toLowerCase();
  if (allowed.indexOf(choice) === -1) throw new Error(name + ' must be one of: ' + allowed.join(', ') + '.');
