function httpsUrl(value, fallback, name) {
  const url = (isBlank(value) ? fallback : String(value).trim()).replace(/\/+$/, '');
  if (!/^https:\/\//i.test(url)) throw new Error(name + ' must use https:// (received "' + url + '").');
